import './Login.css';
import Container from 'react-bootstrap/Container';
import Row from 'react-bootstrap/Row';
import Col from 'react-bootstrap/Col';
import { useEffect, useState } from 'react';
import api from './Axios';

function Admin() {

    const [users, setUsers] = useState([]);
  
    useEffect(() => {
      const loadUsers = async () => {
        console.log("Fetching users...");  // ✅ Debugging log
        try {
            const result = await api.get("/api/admin/users", {
                headers: {
                    "Content-Type": "application/json",
                    "Authorization": `Bearer ${token}`,
                    "Accept": "application/json",
                },
        });
            console.log("Users fetched:", result.data);  // ✅ Log the response
            setUsers(result.data);
        } catch (error) {
            console.error("Error fetching users:", error);
        }
    };
      loadUsers();
    }, []);

    return(
        <div fluid>
            <Container style={{width:"100%", paddingTop:"1.5rem"}}>
                <Row>
                    <Col style={{paddingBottom:"1.5rem"}}>
                        <h1>Admin</h1>
                    </Col>
                </Row>
                <Row>
                    <Col>
                    <table className="table border shadow">
                        <thead>
                            <tr>
                            <th scope="col">#</th>
                            <th scope="col">Email</th>
                            <th scope="col">Username</th>
                            <th scope="col">Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {
                                users.map((user,index)=>(
                                    <tr>
                                    <th scope="row" key={index}>{index + 1}</th>
                                    <td>{user.email}</td>
                                    <td>{user.username}</td>
                                    </tr>
                                ))
                            }
                        </tbody>
                    </table>
                    </Col>
                </Row>
            </Container>
        </div>
    )
}

export default Admin;
